{
  "schemaVersion": "0.2",
  "slug": "number-input",
  "name": "NumberInput",
  "status": "experimental",
  "purpose": "Captures a numeric value with increment and decrement controls.",
  "scenarios": [
    "Enter a quantity",
    "Set a price",
    "Choose an age"
  ],
  "props": {
    "value": {
      "type": "number",
      "required": true,
      "description": "Current value."
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called when value changes."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Input label."
    },
    "min": {
      "type": "number",
      "required": false,
      "description": "Minimum value."
    },
    "max": {
      "type": "number",
      "required": false,
      "description": "Maximum value."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Input rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "page",
      "dialog"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for arbitrary text.",
    "Do not omit the label."
  ],
  "a11y": {
    "role": "spinbutton",
    "keyboard": [
      "Arrow keys increment/decrement"
    ],
    "focus": "Input is focusable.",
    "labeling": "Label provides the accessible name.",
    "wcag": [
      "3.3.2",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Native number input with styled label.",
    "breakpoints": {
      "compact": "Full width.",
      "medium": "Inline width.",
      "large": "Inline width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "number-input",
    "states": [
      "default"
    ],
    "intents": [
      "enter-quantity"
    ]
  }
}

import { FieldPrimitive } from '@chameleon-ui/primitives'
import './styles.css'

export interface NumberInputProps {
  value: number
  onChange: (value: number) => void
  label: string
  min?: number
  max?: number
  className?: string
}

export function NumberInput({ value, onChange, label, min, max, className }: NumberInputProps) {
  const classes = ['cu-number-input', className].filter(Boolean).join(' ')
  return (
    <FieldPrimitive.Root className={classes} data-ai-role="number-input" data-ai-state="default" data-ai-intent="enter-quantity">
      <FieldPrimitive.Label className="cu-number-input__label">{label}</FieldPrimitive.Label>
      <FieldPrimitive.Input
        className="cu-number-input__input"
        max={max}
        min={min}
        onChange={(event) => onChange(Number(event.currentTarget.value))}
        type="number"
        value={value}
      />
    </FieldPrimitive.Root>
  )
}

.cu-number-input {
  display: grid;
  gap: var(--cu-space-1);
}

.cu-number-input__label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--cu-color-fg-default);
}

.cu-number-input__input {
  min-block-size: 2.75rem;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-default);
  font: inherit;
}

.cu-number-input__input:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}
